            "이 사건 면책조항(글라이더 조종, 스카이다이빙, 행글라이딩 등)은 제한적, 열거적인 것으로 해석해야 하며, 패러글라이딩은 위 열거사유에 해당하지 않으므로, 패러글라이딩으로 인한 사고는 면책사유에 해당한다고 보기 어렵다. 따라서 원고의 이 부분 주장은 이유 없다.",
            "피고가 2014. 10. 20. '보험금 청구 권리 포기서'를 제출함으로써 이 사건 사고로 인한 보험금 청구권 일체를 포기하였으므로, 원고의 피고에 대한 보험금 지급채무는 존재하지 아니한다.",
            "피고의 착오는 동기의 착오에 해당하며, 피고가 동기를 원고에게 표시했거나 착오가 원고로부터 유발되었음을 인정할 증거가 부족하다. 또한 포기서는 피고의 일방적인 의사표시이므로 쌍방의 일치된 착오에 의한 의사표시가 있을 수 없다. 피고는 수사기관 처벌에 대한 두려움으로 자발적으로 포기서를 작성한 것으로 보인다. 따라서 피고의 착오 취소 주장은 이유 없다.",
            "원고가 피고를 기망했다는 증거가 부족하므로, 피고의 기망 취소 주장도 이유 없다.",
            "원고의 이 사건 청구(채무부존재확인)는 이유 있어 인용한다."
