            "보험사는 사고 경위에 대한 의심이 있을 경우, 진료기록, 관련 정황, 피보험자의 직업 등을 종합적으로 검토하고, 필요한 경우 수사기관 의뢰 등을 통해 사실관계를 명확히 할 수 있다."
