            "- 담당 의사의 소견과 달리, 원고의 진료기록상 이 사건 수술 중 후낭파열이 발생한 것으로 보이지 않고, 수술 이후에도 후낭파열과 관련한 특별한 관찰이나 관리가 필요하였다거나 그러한 관찰·관리가 실제 이루어졌던 것으로 보이지 아니하며 달리 원고에게 입원이 필요한 특별한 사정이 있었음을 인정할 자료가 없다.",
